import * as THREE from 'three';
const geo = new THREE.BufferGeometry();
const positions = new Float32Array([
-1, -1, 0,
1, -1, 0,
0, 1, 0,
]);
geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
geo.computeVertexNormals(); // generates per-vertex normals from triangle facets
geo.setIndex([0, 1, 2]); // optional — explicit triangle vertices
const mesh = new THREE.Mesh(geo, new THREE.MeshStandardMaterial({ color: 0x88ddff }));
scene.add(mesh);
Direct array control is what you reach for when generating procedural geometry (terrain, ribbons, particles). For everyday primitives, use the built-ins.

Quick stylised looks without writing a shader:
// low-poly facet style
new THREE.IcosahedronGeometry(1, 1); // detail=1 → 80 tris
new THREE.MeshStandardMaterial({ color: 0x66ccff, flatShading: true });
// wireframe outline
const wf = new THREE.WireframeGeometry(geo); // distinct from material.wireframe
scene.add(new THREE.LineSegments(wf, new THREE.LineBasicMaterial({ color: 0xffffff })));
// edges only (cleaner than wireframe)
const edges = new THREE.EdgesGeometry(geo, 30); // 30° angle threshold
scene.add(new THREE.LineSegments(edges, new THREE.LineBasicMaterial({ color: 0xffffff })));
EdgesGeometry is the right tool for "outline the silhouette of this object" without dotting every triangle.

Three.js does not garbage-collect GPU resources automatically. When removing meshes:
scene.remove(mesh);
mesh.geometry.dispose();
mesh.material.dispose();
// also dispose any textures the material referenced
mesh.material.map?.dispose();
Forgetting this in a long-running app causes GPU memory to climb until the tab crashes. Especially important when loading and unloading scenes / models.
A helper:
function disposeObject(obj) {
obj.traverse((c) => {
if (c.geometry) c.geometry.dispose();
if (c.material) {
const mats = Array.isArray(c.material) ? c.material : [c.material];
for (const m of mats) {
for (const k in m) if (m[k]?.isTexture) m[k].dispose();
m.dispose();
}
}
});
}
